insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('7198b937-5926-59ce-9a3c-4fdf5bf2e086', 'abercrombie', 'women', 'bottoms', 'Classic', 'body', '"Sizes are designed to fit the following body measurements"; columns "Your Waist (cm)", "Your Hips (cm)"', 'cm', 'letter', 'https://www.abercrombie.com/shop/eu/p/high-rise-90s-relaxed-jean-60561868', 'brand_site', null, '2026-10-04', null, 'draft', 'abercrombie.com redirects to the EU store from this location, and there is no standalone size-chart page (/help/size-charts returns 404); the chart was read from the product-page "Size Guide" dialog with region EU and CM selected. An IN option and USA/Italy/UK/Japan/Korea/China region views exist but were not captured, so no US aliases are recorded. Curve Love has the same waist ranges with larger hips (fit_line). Range ends are shared between neighbouring sizes (e.g. 60 ends 23 and starts 24). EU aliases repeat (25 and 26 are both EU 36). Inseam is not per size: lengths are Extra Short / Short / Regular / Long (an Extra Long length is sold but has no height band). The same dialog shows per-product garment measurements (e.g. Regular Inseam 31.50 for size 28 / 6) that vary by style; not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
