insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('581a7f61-6766-5ded-aaf0-8ec8e6a4de65', 'ag', 'women', 'general', null, 'body', 'No measuring instructions on the page; the chart lists Hip and Bust as ranges per size (e.g. Hip "86.5 - 89", Bust "79 - 81.5"), which is the form of a body-measurement chart. Basis inferred, not stated.', 'cm', 'denim_waist', 'https://www.agjeans.com/pages/womens-size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'The first column is headed ''Waist'' but holds the denim size (23-34) and is identical in the INCH and CM tables, so it is a size label, not a measured waist; waist is therefore null. Letter size, hip and bust cells span two denim sizes (rowspan), so both sizes in each pair share the same hip/bust range. Sizes 26 and 27 are both published as US 4 (no US 4/6 split). The XXL hip/bust cells have rowspan=2 but there is no size 35 row. The page gives no body-vs-garment wording; ''body'' is inferred from the range format. Inches also published (hip 33, 34-35, 36-37, 38-39, 40-41.5, 42.5-44, 45-46.5; bust 30, 31-32, 33-34, 35-36, 37-38.5, 39.5-41, 42-43.5). No inseam chart.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
