insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('b4137a26-c338-5e7e-a012-df04bff1c0a8', 'agolde', 'women', 'general', null, 'body', 'Size chart image gives no body/garment wording; it lists BUST, WAIST, HIP per size including bust for denim sizes (body-chart form). The AGOLDE fit guide''s How to Measure says Waist: "Measure around the natural waistline, keeping the tape comfortably loose." Basis inferred.', 'cm', 'denim_waist', 'https://agolde.com/pages/agolde-size-chart', 'brand_site', null, '2026-10-04', 'NOTE: THESE GUIDES PROVIDE GENERAL SIZING INFORMATION, WHICH CAN VARY DEPENDING ON STYLE.', 'draft', 'Chart is published only as an image (https://cdn.shopify.com/s/files/1/0269/4076/8349/files/AGOLDE_SIZE_CHART_WEBSITE.jpg, 1002x1012); values read visually. It is numerically identical to the Citizens of Humanity women''s chart (same parent company). Letter labels published as X-SMALL..X-LARGE (abbreviated XS..XL), each spanning two denim sizes; 22, 23, 34 have no letter; 22-24 have no US size; US 10 spans 30-31, US 12 spans 32-33. Inches also published (bust 29 1/2..41 1/2, waist 22 1/2..34 1/2, hip 32 1/2..44 1/2). The ''How to Measure'' block on the Fit Guide 2.0 page mixes body (waist) and garment (rise, inseam, leg opening) instructions, and its embedded size-chart images are broken placeholders. No per-size inseam.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
