insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('cfcb1b23-2a0b-5cb0-bdcb-17cd03283bd4', 'anine-bing', 'women', 'jeans', 'same chart, inch table (see problems)', 'body', 'Chart image ("DENIM SIZING", shown in the product-page Size guide dialog) marks WAIST / LOW HIP / THIGH on a model''s body; garment specs are listed separately per product as "Product Measurements (Size 27): ... Waist: 30\", Hip: 39\"". No explicit "body measurements" wording.', 'in', 'denim_waist', 'https://www.aninebing.com/cdn/shop/files/FIT_GUIDE_DESKTOP_2.jpg', 'brand_site', null, '2026-10-04', 'The fit and sizing of our denim varies by style. Visit the individual denim product pages for more information.', 'draft', 'The size guide is published only as images on aninebing.com (shown in the product-page "Size guide" dialog); values were read from the images, and are not in page text. The cm table looks WRONG against the inch table, which is internally consistent: size 27 low hip 92 cm is smaller than size 26 (93 cm), and waist jumps 74 to 79 between 29 and 30 (inch table: 29 to 30). Per the rules the cm chart is listed first, but the inch chart is probably the reliable one; confirm with the brand. Hip is labelled "LOW HIP". Rows carry an extra "thigh" field. No inseam in the chart (inseam is in the style name, e.g. "Hugh Jean 32"). The guide itself says denim fit varies by style. The general chart is conversion only; its unit field is meaningless; the label is the "AB SIZE" pair (US / FR) and two columns are both S (4 / 36 and 6 / 38). The search-result summary quoting 29 = 29.5" waist did not match the current image.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
