insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('4a76fd21-916e-5cee-b965-71d3667fcf05', 'calvin-klein-jeans', 'women', 'jeans', 'Calvin Klein Jeans Bottoms', 'body', '"How To Measure Myself? Waist: Measure around 5cm below natural waist where the waistband of trousers normally sits on the body."', 'cm', 'denim_waist', 'https://www.calvinklein.co.uk/womens-size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'Source is the Calvin Klein UK women''s size guide (calvinklein.us returned 403 to scripted fetches; the UK page is the brand''s own site). Inches tables also published. Waist sizes 35 and 36 have conversions (letter, US) but EMPTY measurement cells, and EU/UK/FR/IT cells are empty for 35-36; recorded as null. Size 24 conversions are published as "＜ 32" etc. (full-width less-than sign kept). Waist ranges are not contiguous at 29/30 (72.39 - 74.39 then 74.39 - 77.47, i.e. a 2.0 cm band) and look inch-derived. No inseam values are given. Rows carry an extra "thigh" field. The page also has a "Womenswear Bottoms" chart (sizes 34-46) for the Calvin Klein main line, not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
