insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('5e065da6-d620-503f-ba01-030a5ae4747b', 'citizens', 'women', 'general', null, 'body', 'No measuring instructions on the page; the chart (an image titled "WOMEN''S") gives BUST, WAIST, HIP per size including bust for denim sizes, which is the form of a body chart. Basis inferred, not stated.', 'cm', 'denim_waist', 'https://citizensofhumanity.com/pages/coh-size-chart', 'brand_site', null, '2026-10-04', 'Note: These guides provide general sizing information, which can vary depending on style.', 'draft', 'Chart is published only as an image (https://cdn.shopify.com/s/files/1/0252/1042/1345/files/COH_SIZE_CHART_WEBSITE_WOMENS_1_2048x2048.jpg); values read visually from the 1800x1200 image, worth a second visual check. Letter labels are published as X-SMALL/SMALL/MEDIUM/LARGE/X-LARGE (abbreviated here to XS..XL) and each spans two denim sizes; sizes 22, 23 and 34 have no letter, and 22-24 have no US size. US 10 spans 30-31 and US 12 spans 32-33. Inches also published (bust 29 1/2..41 1/2, waist 22 1/2..34 1/2, hip 32 1/2..44 1/2, in 1-inch steps). The page gives no body-vs-garment wording. No inseam chart; the separate Women''s Denim Guide (citizensofhumanity.com/pages/womens-denim-guide) gives per-style garment specs (rise, leg opening, inseam) for a single sample size, not per-size rows, so it was not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
