insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('3e43ffe6-3d11-52d1-8228-77d7b5aa961a', 'diesel', 'women', 'jeans', 'Diesel Size Chart (women''s jeans, product-page size chart panel)', null, 'Not applicable: the official Diesel Size Chart is a conversion table only and publishes no body or garment measurements.', null, 'denim_waist', 'https://uk.diesel.com/en/regular/regular-jeans-1971-d-sent-007ei-blue/A19869007EI01.html', 'brand_site', null, '2026-10-04', null, 'draft', 'Diesel''s own site (uk.diesel.com and diesel.com/en-us, women''s jeans product pages, ''Size chart'' panel) shows only a conversion table (Diesel Size / Intern. Size / Ita / Us / De / Fr/Es / Uk / Ru) with no waist or hip measurements; the women''s denim guide (global.diesel.com/woman/denim-guide/) describes fits only. The table is staggered: Diesel sizes 23, 25, 27-31 and 33 each straddle two rows of the conversion columns, so those aliases are recorded as ''A/B'' exactly as the spans fall (e.g. 28 spans IT 42 and 44). measurement_basis and unit are null because no measurements exist. Third-party sites (footshop.eu, size-charts.com) publish waist/hip cm values labelled as Diesel, but they are not the brand''s chart and were not used. Extra alias keys used: it, de, fr, uk, ru.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
