insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('b1b027db-5452-5771-9984-3fc58f5173e9', 'dr-denim', 'women', 'jeans', 'Arch Mid Straight', 'garment', '"Measure a pair of your favorite jeans and compare to the table below to find the perfect fit!"; How to measure page: "Please lay a pair of your jeans flat on a smooth and even surface, then measure."', 'cm', 'denim_waist', 'https://drdenim.com/products/arch-mid-straight-tar-mid-grey-retro', 'brand_site', null, '2026-10-04', 'Inseam by length option: 74.6/79.5/84.5 (same for every size, as published)', 'draft', 'Dr. Denim publishes no body-measurement chart: drdenim.com/pages/size-guide is 404 and the How to measure page says to measure a pair of your own jeans laid flat. Each product page carries a per-style GARMENT table (CM): Waist (flat, i.e. half circumference, e.g. 32.35 for size 24), Rise, Thigh, Inseam, Leg opening. No hip measurement is published, so hip is null everywhere. One product per women''s jeans style (27 styles with tables) was read on 2026-10-04 via the store''s product pages; 15 styles had no table (Echo High Straight, Echo High Straight Button, Echo Mid Straight, Zila Mid Wide, Zila Mid Wide Patch Pocket, Straw Mid Slim, Kily Low Bootcut, Ary Low Baggy, Rhue High Wide, Rhue High Wide Pleated, Lexy Mid Skinny Preggo, Moxy Petite, Moxy Tall, Moxy Tall High Skinny, Solitaire High Petite). Some styles are sized XS-XL, others 24-32. Inseam values like 76/81/86 are per length option, so per-row inseam is null and the options are in fit_advice. Inconsistencies copied as published: ''Donna'' and ''Donna High Relaxed'' have identical waists but inseams 78/83/88 vs 76/81/86; Nika Mid Straight (and Worker) inseam reads 72/87/82 (likely a typo for 72/77/82); Arch size 25 and 26 share waist 34.5; Plenty Mid Skinny L waist 36 vs XL 37. Waist values are garment half-measurements and must not be compared directly to body circumference.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
