insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('13a1f5dd-d416-5e03-a18b-01620a918c04', 'frame', 'women', 'jeans', 'Size-Spanning', 'body', 'Table has no visible caption; the site''s size-guide script builds it with the title "Body Measurements", and the modal section heading is "Product Measurements". No measuring instructions shown. Basis is ambiguous; body is the more likely reading (waist equals the size number).', 'in', 'mixed', 'https://frame-store.com/products/the-borrowed-au-natural-clean', 'brand_site', null, '2026-10-04', null, 'draft', 'FRAME has no standalone size-guide page (all /pages/size-guide variants 404); charts live in the per-product ''Size & Fit'' modal and were read from the page''s embedded data. Values are published in inches; the CM toggle is computed client-side, so inches were recorded. Denim conversion table''s first column is headed ''US'' but holds the denim size (23-34); UK/IT/FR aliases kept as published. Conflict: size 34 hip is 43.5 in on denim product pages but 44.5 in in the ''Measurements Bottoms (in.)'' table on apparel product pages (all other bottoms values match); 43.5 recorded from the denim page. The apparel chart has unusual steps: M waist 27.5-28.5 overlaps S/M 27-27.75, and bust jumps from 36-37 (M/L) to 40-42 (L); both XXS and XS map to FR 32 and US 0/00. Size-spanning sizes 0/1/2 appear in the denim modal of every jean checked (unclear whether they apply to that style). Product modals also show per-style garment specs (rise, inseam, leg opening) for one size, not recorded. Basis is not stated in visible text for any chart.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
