insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('ff9886ba-b148-5dae-b86b-02e63d9ab1d7', 'g-star-raw', 'women', 'jeans', 'waist sizes', 'body', 'How-to-measure text on the guide: "Waist Measure around waist at the smallest part just above the navel." / "Hip Measure around hip at the fullest part of buttocks."', 'cm', 'denim_waist', 'https://www.g-star.com/en_us/size-guide?gender=women&guide=bottoms&unit=cm', 'brand_site', null, '2026-10-04', null, 'draft', 'Tables identified by their DOM classes (js-measurementsTable--women / --bottoms / --wl etc.) because the page shows them via selectors. Inches tables also published. The numeric-size conversion table has no rows for 22, 35, 36; it maps 23 to US "x" (omitted) and both 24 and 25 to US 0. Waist and length are separate charts (e.g. W27 L32): inseam is only in the length chart. Tops chart also gives arm length (not recorded). A third-party search summary showed a 24-44 numeric chart starting 64/78 cm: that is the MEN''s table, not women''s.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
