insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('585345fb-fdc4-5eac-9602-2063ac5c616e', 'hm', 'women', 'general', null, 'body', 'Measurements should be taken directly on your body.', 'cm', 'eu', 'https://www.hm.com/om/customer-service/sizeguide/ladies/', 'brand_site', null, '2026-10-04', null, 'draft', 'The en_gb customer-service size guide URL now redirects to a FAQ saying the guide lives on product pages; the tables were read from the H&M Oman (hm.com/om) customer-service guide, H&M''s own site. Letter sizes span two EU sizes each (XS = 32-34 ... 4XL = 60-62, header colspan 2). The general chart covers trousers too and gives one inside-leg value, 79 cm, for every size. The jeans table is only a conversion (waist-inch labels grouped per letter/EU pair, no measurements); exact inch-to-EU pairing inside each group is not published, so groups are stored as-is. Bust measurement listed as ''Bust (cm)'', hip as ''Seat (cm)''. Product-page guides for specific markets were not cross-checked.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
