insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('6f36eb0d-b31d-5cd3-bb56-ad8f9d1bd7e5', 'khaite', 'women', 'trousers', null, 'body', 'No explicit body/garment wording. Size Guide page lists Waist/Low Hip per size with the note "Email a stylist for size and fit advice"; values follow a standard body-measurement grading (identical across Dresses, Knitwear, Coats), so treated as body', 'cm', 'us', 'https://khaite.com/pages/size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'The main size guide says for Denim: "Please see fit and size information on our denim product pages, as they vary by style." There is no single denim chart; three product charts recorded (inches only, fractions such as 33 1/2 written as decimals; rows carry an extra "rise" field). Even the same style differs by wash (Danielle Lykens vs Montgomery), so a per-product chart is needed for accuracy. None of the charts says whether values are body or garment; basis is inferred. Pants/dresses inches tables also published (e.g. size 0 waist 25.5, low hip 35.75); hip is labelled "Low Hip". Pants chart labels size 12 as L while the dresses chart labels it XL.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
