insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('c1aead55-7288-5567-80ce-6a9c46a9dbb9', 'khaite', 'women', 'jeans', 'Dane Stretch Jean (Carlyle)', 'garment', 'Product "Denim Size Guide" gives Waist/Hip/Inseam/Rise per size and varies by product; it includes a fixed Inseam and a Rise, which are garment specifications. No explicit wording either way.', 'in', 'denim_waist', 'https://khaite.com/products/dane-stretch-jean-in-carlyle', 'brand_site', null, '2026-10-04', 'True to size. Recommended to take your normal size. Model is 5’10, wearing size 26.', 'draft', 'The main size guide says for Denim: "Please see fit and size information on our denim product pages, as they vary by style." There is no single denim chart; three product charts recorded (inches only, fractions such as 33 1/2 written as decimals; rows carry an extra "rise" field). Even the same style differs by wash (Danielle Lykens vs Montgomery), so a per-product chart is needed for accuracy. None of the charts says whether values are body or garment; basis is inferred. Pants/dresses inches tables also published (e.g. size 0 waist 25.5, low hip 35.75); hip is labelled "Low Hip". Pants chart labels size 12 as L while the dresses chart labels it XL.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
