insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('5382e33d-4ca5-5eaa-a557-88ddc98fa9b7', 'lee', 'women', 'tops', 'WOMEN''S Tops (bust = Chest; hip = Seat)', 'body', '"All measurements should be taken directly on the body." (WOMEN''S TOPS MEASURING TIPS)', 'cm', 'letter', 'https://eu.lee.com/uk-en/LEE-SIZECHART-BOTTOMS-WOMEN.html', 'brand_site', null, '2026-10-04', 'If your measurements suggest different sizes, your hip measurement is leading. If your measurement is in between two sizes, order the smallest size for a tighter fit or the bigger size for a looser fit.', 'draft', 'Lee EMEA page publishes cm and inch tabs (cm recorded; values with ½ recorded as .5). It lists Natural Waist, Low Waist (5cm below natural), Seat and Thigh; only Natural Waist and Seat are recorded. The International Sizes jeans table shows Seat 64 for size 23, which is almost certainly a typo on the page (neighbours 81 and 86); copied as published. The International table''s whole-number Waist/Seat differ slightly from the main jeans table (e.g. size 24: 64 vs 63.5) and its tops chest values differ from the WOMEN''S Tops tab (M: 95 vs 93.5); both kept as separate charts. US alias 10 appears for both 30 and 31, 16 for both 34 and 35, 18 for both 36 and 37. The EU (eu.lee.com) and US (lee.com) charts differ substantially (EU 27 natural waist 71cm vs US 27 waist 28-28½in); both are included, US charts are in inches. On lee.com the size column has three parts (alpha, numeric US size, and a denim size 24-40 with no header text); the third is stored as alias ''denim_waist'' and the row label is the US numeric size. The US alpha is rowspanned over two numeric sizes (e.g. XS = 0 and 2). The lee.com plus tops table also lists Waist values equal to Hips in one copy of the table (a page inconsistency); plus tops were not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
