insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('3d2e1023-e63f-522d-84c5-9d5d19a0b883', 'levis', 'women', 'bottoms', null, 'body', 'WAIST: "Measure around the smallest part of your waist. Not too snug, not too loose."', 'in', 'denim_waist', 'https://www.levi.com/US/en_US/info/sizeguide', 'brand_site', null, '2026-10-04', null, 'draft', 'Inseam is not a body measurement per size; the guide gives a height-to-inseam table instead: 5''1" or shorter -> 28; 5''2"-5''3" -> 30; 5''4"-5''7" -> 32 (alpha M); 5''8" or taller -> 34 (alpha L). Tops chart ''bust'' is the published CHEST column; the ''lmc'' alias is the published ''LMC(TM) SIZE'' column (Levi''s Made & Crafted). Plus tops (1X-3X, numeric 14-24) and dresses charts exist on the same page and were not recorded; the plus tops and plus dresses tables place the 1X/2X/3X labels against different numeric rows (tops: 1X=14, 2X=18, 3X=22; dresses: 1X=16, 2X=20, 3X=24). Page served from levi.com US; content loads via JavaScript (read in browser).') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
