insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('f603c975-a989-50b3-ae8e-07ff29962187', 'madewell', 'women', 'tops', null, 'body', 'Column headers read "YOUR BUST | YOUR WAIST | US SIZE"', 'in', 'us', 'https://www.madewell.com/c/size-chart/', 'brand_site', null, '2026-10-04', null, 'draft', 'Recorded in inches: the page has an in/cm toggle but scripted clicks did not switch the tables, so cm values were not captured (not converted). Length guidance is separate: Petite 5''3" and under, Short 5''5" and under, Standard between 5''4" and 5''9", Tall 5''9" and over; "Designed for 5''4" to 5''8" with a 30" to 32" inseam." No per-size inseam. INCONSISTENCY: the page FAQ says "A women''s jeans size 28 refers to a 29-inch waist" while the Regular Denim chart gives 29.25". Plus sizes overlap: 33 (37.5") vs 14W (37"); 18 appears as both XXL and 1X with identical measurements; 0 / XS covers two rows (25" and 26"). Many third-party sites quote an older Madewell chart (24 = 25" waist); that is not what madewell.com shows today. A hidden alternate bust/waist/hip table (000/XXXS to 24W/3X) exists in the page DOM but is not displayed; not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
