insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('1579a2d9-a391-5e39-a076-02f46d829839', 'mango', 'women', 'dresses', null, 'body', 'Product-page ''MEASUREMENTS'' panel, tab labelled ''BODY''; ''Measure around the narrowest part of the abdomen.''; Hip: ''Measure the circumference at the widest point.''', 'cm', 'uk', 'https://shop.mango.com/ie/en/p/women/dresses-and-jumpsuits/dresses/asymmetrical-pleated-dress/37037940/49/00', 'brand_site', null, '2026-10-04', null, 'draft', 'Mango has no standalone size-guide page (shop.mango.com/gb/en/help/size-guide is a 404); charts are the per-product ''Measurements'' panels, read on the Ireland store (the GB store shows the same panel in inches only by default). Product size buttons are labelled with UK numbers (4-18); the panel''s equivalents table maps them to Europe 32-46, which is used as the label for jeans/trousers. The flared jeans and the wool suit trousers showed identical charts. Bottoms charts give waist and hip only, no inseam. Letter tops (t-shirt) give bust and waist only, no hip, and no EU-number equivalent (the equivalents table repeats letters). The dress chart is labelled by UK size with letter/US equivalents from that product''s table; it covers only UK 6-14 on that product. Note the dress chart''s waist for UK 10 / M is 72 cm while the bottoms chart''s EU 38 / UK 10 is 70 cm; the charts differ and are kept separate. Charts are per product and may vary across products.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
