insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('cb1ddb64-8b70-53a0-9520-4fd66443fc12', 'mother', 'women', 'jeans', 'Women''s Stretch Denim and Tops', 'body', 'Waist: "Measure at the smallest part of your waist. This is usually below the rib cage and above the hip bone."', 'in', 'denim_waist', 'https://www.motherdenim.com/pages/size-guide', 'brand_site', null, '2026-10-04', 'Note: this guide provides general sizing information, which can vary depending on style.', 'draft', 'The chart is titled ''Women''s Stretch Denim and Tops'' and covers both denim and tops; no separate non-stretch chart was found. Source data is in inches; the page''s cm toggle is computed client-side (value x 2.54, rounded to 1 decimal), so inches were recorded as the published unit. ''bust'' is the published Chest row. Letter labels published as X-Small/Small/Medium/Large (abbreviated XS..L), each spanning three denim sizes. The France conversion list is malformed in the page data (11 entries, one cell ''40<tab>42''), so it misaligns from size 30 up and was omitted; the Brazil list also has only 11 entries for 12 sizes and was omitted. Australia equals United Kingdom and was not repeated. The US URL geo-redirects to /en-fr/ in a browser; data read from the page''s embedded size_guide script.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
