insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('34d3f638-2344-5242-9873-204b48508b84', 'noisy-may', 'women', 'general', 'Clothing (aliases from SIZE CONVERSION table)', 'body', 'Section heading "BODY MEASUREMENT"; "Chest - Measure around the fullest part of the bust, while wearing a bra that fits."', 'cm', 'letter', 'https://www.noisymay.com/en-gb/sizeguide/', 'brand_site', null, '2026-10-04', null, 'draft', 'The jeans SIZE CONVERSION table lists letter ''SX'' for size 25, almost certainly a typo for XS; copied as published. EU 36 maps to both 26 and 27, 38 to 28 and 29, 42 to 31 and 32. Jeans run only 25-32 on this guide. No inseam table is published (a generic HOW TO MEASURE note defines inseam only). The HOW TO MEASURE block uses the word ''width'' (''Waist width: Measured at the narrowest part of the waist''), which could read as garment, but the tables sit under a ''BODY MEASUREMENT'' heading, so body was recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
