insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('69b56199-3e72-53a4-a225-eeb3ee6f14c0', 'only', 'women', 'general', 'ONLY SIZE GUIDE (women; jeans sizes given as an alias column)', 'body', 'Table columns sit under the heading "BODY MEASUREMENTS"; "B. WAIST Measure around the narrowest part of your waistline." "C. HIP Measure the fullest part of your hips."', 'cm', 'eu', 'https://www.only.com/en-dk/content/size-guides/size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'The official guide is a single image (store-assets-static-2024-w24-update1-smart-widget-contentpage-on-sizeguide-en.jpg) on only.com/<locale>/content/size-guides/size-guide; values were transcribed visually from the full-resolution image, so a second check is advisable. The product-page ''Size guide'' button failed on en-gb (its /en-gb/sizeguide endpoint 404s) and sizeguide.only.com was ''Server Unavailable''. There is no separate jeans waist/hip table: jeans sizes appear only as a column (27-28, 30-31, 32-33, 34-35 share a row), so a denim-size lookup must go through this general chart. The XXXL row has no EU/UK/US/jeans size; its label is XXXL. A search snippet quoted a different ONLY jeans table (waist 59.5..84.5, hip 86.5..111.5 for 24..34) from an unidentified, possibly older source; it could not be found on the brand site and was not used. Letter values like ''L-XL'' are copied as printed.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
