insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('435288b1-41c3-55ea-a493-99edb0961141', 'other-stories', 'women', 'general', null, 'body', 'HOW TO MEASURE: ''Measure your chest around the fullest part of your bust while wearing a bra that fits well.''', 'cm', 'eu', 'https://www.stories.com/en-gb/customer-service/size-guide/', 'brand_site', null, '2026-10-04', 'As the sizes may vary between our products, we recommend that you also have a look at the specific measurements provided in the product descriptions.', 'draft', 'Clothing, Denim and Swimwear accordions show identical body tables; Denim is sized by EU number, not waist inches. Letters span two EU sizes (XS = 32/34, S = 36/38, M = 40/42; L = 44 only). The ''size converter'' view publishes UK/IT/FR-ES per letter as ranges (e.g. XS: UK 4-6, IT 36-38, FR/ES 34-36); those ranges are stored unsplit on both EU rows of each letter. Bust column labelled ''Chest''. Inseam 79 for every size. Chart tops out at EU 44.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
