insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('72a9d33b-339e-5b6d-99eb-eab27e8e444a', 'paige', 'women', 'tops', null, 'body', 'Waist: "Measure around your natural waistline, about two inches above your belly button."', 'cm', 'letter', 'https://paige.com/size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'Letter sizes repeat across rows (XS, S, M, L and XXL each cover two rows), so a letter label is not unique in the apparel chart; rows are kept in published order. The last apparel row (XXL, waist 91.5 cm / 36 in) has no US size and no bust. The apparel chart is labelled ''APPAREL'' on the page; category ''tops'' chosen because it gives bust and waist only (no hip). Inches also published (denim waist 23..30, 31.5, 33, 34.5, 36; hips 33..40, 41.5, 43, 44.5, 46; apparel bust 31..38, 38.5, 40, 41.5). A separate Women''s Maternity denim chart exists (sizes 23-34, inches waist 33-46) and was not recorded. No per-size inseam chart. The page geo-redirects to /en-fr/size-guide; content read in the browser after declining cookies.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
