insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('17506dd1-5e0b-5143-a302-273b26d9c825', 'pepe-jeans', 'women', 'tops', 'Women''s SHIRTS size guide, DENIM SIZE table', 'body', 'Site size-guide copy: "How to take body measurements" ... "BUST: Measure around the fullest part of your bust and shoulder blades by dropping your arms loosely to the sides." "WAIST: Measure around your natural waistline at the belly button." "HIP: Measure at the widest part of your hip." Table rows are labelled WAIST CIRC. / HIP CIRC.', 'cm', 'letter', 'https://www.pepejeans.com/uk/en_gb/pd/ornamental-print-fluid-blouse-PL3051569.html?color=765', 'brand_site', null, '2026-10-04', null, 'draft', 'No standalone size-guide page works any more: pepejeans.com/en_gb/pepejeans-size-guide-ladies-jeans.html and /uk/en_gb/size-guide.html return ''page can''t be found''; the charts were read from the ''View Size Chart'' panel on UK product pages (Venus jeans, a fluid blouse), which may be the generic category chart. Body-vs-garment wording (''How to take body measurements'') comes from the site''s size-guide copy embedded in the page, not from text visible in the panel itself. The panel offers CM/IN toggles; cm recorded. The jeans conversion tab gives EU 34..44 (with 34/36-style halves) whereas the shirts conversion tab maps the same 24-34 sizes to EUR 30..50; both copied as published. UK ''-'' means no UK equivalent published (omitted). Jeans table also gives THIGH; shirts table gives SHOULDER, LONG SLEEVE, BICEPS (not recorded). The jeans length table is per leg length, not per waist size, so it is a separate chart labelled L28..L34 / RE / LO.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
