insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('84b6f9b4-7c23-55fb-8809-f0a5b042008d', 'pull-bear', 'women', 'general', null, 'body', 'Measurements panel, ''Body'' tab: ''* The measurements shown refer to body measurements.'' ''Measure the chest circumference at the widest part of the chest below the armpits''', 'cm', 'letter', 'https://www.pullandbear.com/es/en/boxyfit-long-sleeve-tshirt-l07230388?cS=800', 'brand_site', null, '2026-10-04', null, 'draft', 'No standalone size-guide page found; charts come from the product-page ''See measurements'' panel (''Body'' tab), read on the Spain (English) store, one size at a time. The jeans body chart (Low-rise star straight-leg jeans) gives waist and hip only; inseam appears only on the garment (''Item'') tab as a flat item measurement, so it is not stored. The letter chart was identical on a basic T-shirt and on a Maxi dress (l07380333); bust column labelled ''Chest''. No published EU-number to letter or US/UK equivalence on these panels. Charts are per product and may vary for other products.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
