insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('a3acff1c-aca6-5ade-a79a-8c1bf5f3ab1a', 'redone', 'women', 'jeans', 'High Rise Stove Pipe', 'garment', 'Image titled "Measurements (Inches)" with Waist, Hip, Rise, Inseam and Opening per size for one style; rise and leg opening are garment dimensions, and the product specs state e.g. "11” high rise, 27” inseam, 14.5” leg opening" for the same style.', 'in', 'denim_waist', 'https://shopredone.com/products/high-rise-stove-pipe-medium-vain', 'brand_site', null, '2026-10-04', null, 'draft', 'RE/DONE publishes no general women''s body-measurement chart on its own site (shopredone.com/pages/size-guide is 404; no size page in the sitemap). Each product has its own per-style garment-measurement image, so only two representative styles were recorded; other styles (Comfort Stretch, 70s Bootcut, RE/DONE x Levi''s reconstructed vintage) have their own charts and will differ. Values read visually from 828x205 PNG images (https://shopredone.com/cdn/shop/files/188-3WSTV27.png, https://shopredone.com/cdn/shop/files/141-03W90HRLO_SIZEGUIDE.png); fractions converted to decimals (e.g. 25 1/2 -> 25.5), which is notation only, not rounding. Rise and leg opening per size also published but have no schema field. Stove Pipe fabric is rigid 100% cotton. A retailer conversion table (Smallable: 24/25=FR 34, US 0-2, etc.) exists but was not used because the brand site has charts.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
