insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('42018168-c34f-5d3b-9ad4-449608be6d60', 'tommy-jeans', 'women', 'trousers', 'Tommy Jeans pants', 'body', 'No explicit body/garment wording on the page (no how-to-measure text). Values are given as ranges per size (e.g. WAIST 68 - 70), the form used for body measurements; treated as body.', 'cm', 'letter', 'https://uk.tommy.com/womens-size-guide', 'brand_site', null, '2026-10-04', null, 'draft', 'Source is the Tommy Hilfiger UK women''s size guide, "TOMMY JEANS SIZES" section (nz.tommy.com/size_guide_tommy_jeans_womens publishes the same jeans waist/hip ranges plus 36-42). No body/garment wording anywhere, so basis is inferred. Inches tables also exist. Alias conversions overlap (e.g. 25 and 26 are both EU 34 - 36); the US alias in the pants table is published as "US + UK SIZE 2 - 4" and a separate "US SIZE 00 - 0" row, and the US row was used. INCONSISTENCY: further down the same Tommy Jeans section, tables titled "JEANS - INSEAM 28/30/32/34" give a DIFFERENT single-value grading for the same denim sizes (e.g. 27 = waist 67.3, hips 95.3, US 6, EU 36, inside leg 71.1/76.2/81.3/86.4 cm), and a "SHORTS, SKIRTS, PANTS" table gives XXS-XL waist 60-80 / hips 86-106. These look like a second (possibly older or US) chart; the jeans version is recorded as the ALTERNATE chart, the shorts/skirts/pants one is not. Confirm which one Tommy Jeans products use before relying on it.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
