insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('0a74475a-efe8-5088-b2f8-ed353a590bfd', 'toteme', 'women', 'jeans', 'Classic slim denim (mid waist)', 'garment', 'Product "Size information" table gives WAIST/SEAT/THIGH/RISE and a fixed inseam per length, i.e. flat garment specs; TOTEME labels the same table format "Garment measurements" on non-denim products. Denim pages carry no explicit wording.', 'cm', 'denim_waist', 'https://toteme.com/en-fr/products/classic-slim-denim-full-length-faded-blue', 'brand_site', null, '2026-10-04', null, 'draft', 'TOTEME has no general size-guide page (toteme.com/pages/size-guide returns 404); every chart is a per-product GARMENT chart, so the numbers are the item''s measurements, not body sizes, and they differ by style (a body-to-size mapping needs ease assumptions the brand does not publish). Three current denim styles and one trouser recorded; other styles will differ. Hip is the row labelled "SEAT". Denim inseam depends on the length bought (23/28 ... 32/34), so inseam is null and the per-length values are in inseam_by_length; rows also carry thigh and rise (front_rise for Classic slim). Inches tables also published. Trouser sizes 30 and 44 have garment measurements but no row in the size-conversion table (which covers EU 32-42 with UK, US, IT, AU, RU, JP).') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
