insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('a8458a1f-f361-54af-9e09-61299299e3d0', 'vero-moda', 'women', 'jeans', 'JEANS inseam rows (INSEAM 30"/32"/34"; same value for every waist size)', 'body', '"INSEAM Measure inside of your leg from crotch to ankle bone." plus "How to measure: Measure directly on you body. All measurements are stated in centimetres." (sic)', 'cm', 'denim_waist', 'https://www.veromoda.com/en-gb/sizeguide', 'brand_site', null, '2026-10-04', null, 'draft', 'The official guide is a single image (images.veromoda.com/p/media/sizeguide_vm.jpg) on veromoda.com/en-gb/sizeguide; values were transcribed visually from the full-resolution image (decimal commas such as 65,5 recorded as 65.5), so a second check is advisable. The image also gives BELOW THE BUST (not recorded). Jeans sizes skip 35 (34 is followed by 36). The jeans table repeats the same inseam (76/81/86) for every waist size, so inseam is a separate chart keyed by length. The XS-XL, EU and UK tables are separate and do not line up exactly (e.g. letter M waist 73 = EU 38 waist 73 = UK 10 waist 73, but EU 40 waist 77 has no letter equivalent); no cross-aliases are published, so none were added.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
