insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('f77eee56-1bfd-59d3-b4c8-46f777cd379a', 'weekday', 'women', 'jeans', null, 'body', '"Weekday, Monki and Cheap Monday sizing is based on the same body measurements"; How to measure: "Waist : Measure around your natural waistline, at the smallest part of your waist."', 'cm', 'denim_waist', 'https://www.weekday.com/en-ww/customer-service/size-guide/', 'brand_site', null, '2026-10-04', 'Weekday jeans come in different fits, rises, leg shapes and washes, so start with your usual size, then check the product page for fit notes, fabric details and customer reviews with real sizing feedback.', 'draft', 'Charts are published only as images on the size-guide page ("size-guide-conversion-chart_denim_women" and "..._clothing_women"); values read from the images (decimal commas, e.g. 59,5, written as 59.5). Hip is the row labelled "SEAT CM". The denim chart has no inseam and no waist sizes 35, 37 or 39. In the denim image EUR and letter sizes span columns: EU 32 covers 23-24, 34 covers 25-26, 40 covers 29-30, 42 covers 31-32, 44 covers 33-34; EU 46/48/50 sit over 36/38/40 (adjacent cells are blank). Letter M spans 29-32 in denim but EU 40-42 in clothing. The general chart gives a single inseam 79 cm for every size; "CA" aliases are Canadian-French letter sizes (TTP, TP, P, M, G, TG). The page says Curve jeans exist ("more room through the hip and seat") but no separate Curve chart is published.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
