insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('b534dfb5-25f3-54a2-951e-bf383f7e7f1a', 'wrangler', 'women', 'tops', 'WOMEN''S Tops (bust = Chest; hip = Seat)', 'body', '"All measurements should be taken directly on the body." (WOMEN''S TOPS MEASURING TIPS)', 'cm', 'letter', 'https://eu.wrangler.com/uk-en/WRG-SIZECHART-BOTTOMS-WOMEN.html', 'brand_site', null, '2026-10-04', 'If your measurements suggest different sizes, your hip measurement is leading. If your measurement is in between two sizes, order the smallest size for a tighter fit or the bigger size for a looser fit.', 'draft', 'Wrangler EMEA page publishes cm and inch tabs (cm recorded; values with ½ recorded as .5). It lists Natural Waist, Low Waist (5cm below natural), Seat and Thigh; only Natural Waist and Seat are recorded. The International Sizes jeans table shows Seat 64 for size 23, which is almost certainly a typo on the page (neighbours 81 and 86); copied as published. The International table''s whole-number Waist/Seat differ slightly from the main jeans table (e.g. size 24: 64 vs 63.5) and its tops chest values differ from the WOMEN''S Tops tab (M: 95 vs 93.5); both kept as separate charts. US alias 10 appears for both 30 and 31, 16 for both 34 and 35, 18 for both 36 and 37. The EU chart is identical to Lee EU (same parent company, Kontoor). The US (wrangler.com) Women''s General table''s size column has four parts: alpha, a denim waist size 24-36, a junior size (00, 0, 1, 3 ...) and a misses size (00, 0, 2, 4 ...); stored as label, aliases us_junior and us. Both XS rows are labelled XS, and size 36 shows 22W in both junior and misses columns. The US general table also gives Neck, Sleeve and Thigh, not recorded.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
