insert into public.size_charts (id, brand_id, gender, category, fit_line, measurement_basis, basis_evidence, unit, size_system, source_url, source_type, retailer, retrieved_on, fit_advice, status, notes) values ('f5b591ea-032e-5eee-88bc-b891ad1c77d6', 'zara', 'women', 'jeans', 'TRF MID-WAIST STRAIGHT-LEG JEANS (product 00541211)', 'garment', '''Measurements may show slight variations due to the production process. The garment is measured flat''', 'cm', 'eu', 'https://www.zara.com/es/en/trf-mid-waist-straight-leg-jeans-p00541211.html', 'brand_site', null, '2026-10-04', null, 'draft', 'Zara publishes no general women''s body-measurement size chart: there is no size-guide help page (help-center/SizeGuide is ''PAGE NOT FOUND''), and product pages offer only a per-product ''Measurements'' panel of FLAT GARMENT measurements plus an interactive ''Size recommender''. The two charts here are single-product garment examples, not a brand-wide chart; values are flat (half-circumference) and must not be compared directly with body measurements. Jeans panel also lists total length and rises (machine-translated as ''Front towing eye'' / ''Backfire''), no inseam. Spain store labels the jeans EU 32-46; the Ireland store shows the same product as 4-18 (UK). Dress chart also has chest, total length, sleeve length, arm width (bust stored from ''Chest''). Inches toggle exists.') on conflict (id) do update set measurement_basis = excluded.measurement_basis, basis_evidence = excluded.basis_evidence, unit = excluded.unit, size_system = excluded.size_system, retrieved_on = excluded.retrieved_on, fit_advice = excluded.fit_advice, notes = excluded.notes;
